import currency as tau
import con_gold_contract as gold
__owner = Variable(contract='con_gold_ape_002', name='owner')
__tau_amount = Variable(contract='con_gold_ape_002', name='tau_amount')
__data = Hash(default_value=0, contract='con_gold_ape_002', name='data')
__reserve = Variable(contract='con_gold_ape_002', name='reserve')
__burn = Variable(contract='con_gold_ape_002', name='burn')


def ____():
    __owner.set(ctx.caller)
    __tau_amount.set(1500)
    __reserve.set(
        '96dae3b6213fb80eac7c6f4fa0fd26f34022741c56773107b20199cb43f5ed62')
    __burn.set('0000000000000BURN0000000000000')


@__export('con_gold_ape_002')
def subscribe():
    __gold_price = ForeignHash(foreign_contract=
        'con_rocketswap_official_v1_1', foreign_name='prices', contract=
        'con_gold_ape_002', name='gold_price')
    gold_amount = __tau_amount.get() / __gold_price['con_gold_contract']
    gold.transfer_from(amount=gold_amount, to=ctx.this, main_account=ctx.caller
        )
    __data[ctx.caller] += gold_amount
    __data[ctx.caller, 'start'] = now


@__export('con_gold_ape_002')
def unsubscribe():
    time_delta = now - __data[ctx.caller, 'start']
    if time_delta <= datetime.timedelta(days=30):
        payout = __data[ctx.caller] / 100 * 30
    elif time_delta <= datetime.timedelta(days=90):
        payout = __data[ctx.caller] / 100 * 50
    elif time_delta <= datetime.timedelta(days=120):
        payout = __data[ctx.caller] / 100 * 70
    else:
        payout = __data[ctx.caller] / 100 * 80
    gold.transfer(amount=payout, to=ctx.caller)
    amount_delta = __data[ctx.caller] - payout
    gold.transfer(amount=amount_delta / 2, to=__burn.get())
    gold.transfer(amount=amount_delta - amount_delta / 2, to=__reserve.get())
    __data[ctx.caller] = 0
    return payout


@__export('con_gold_ape_002')
def set_tau_amount(amount: int):
    assert ctx.caller == __owner.get(), 'Only owner can adjust TAU amount'
    assert amount >= 0, "Amount of TAU can't be negative"
    __tau_amount.set(amount)


@__export('con_gold_ape_002')
def deposit_gold(amount: float):
    gold.transfer_from(amount=amount, to=ctx.this, main_account=ctx.caller)


@__export('con_gold_ape_002')
def withdraw_gold(amount: float):
    assert __owner.get() == ctx.caller, 'Only the owner can withdraw GOLD'
    gold.transfer(amount=amount, to=ctx.caller)
